function kaiHumanNeeded(mode){return mode==="signup"||mode==="signin"}
function kaiRecordAuthFailure(){try{const times=JSON.parse(sessionStorage.getItem("kaiAuthFailures")||"[]").filter(t=>Date.now()-t<600000);times.push(Date.now());sessionStorage.setItem("kaiAuthFailures",JSON.stringify(times))}catch{}}
function initKaiHumanCheck(){
 const q=$("kaiHumanQuestion"),host=$("kaiHumanTiles"),answer=$("kaiHumanAnswer"),math=$("kaiHumanMath"),wrap=$("kaiHumanCheck");
 if(!q||!host)return;
 const needed=kaiHumanNeeded(window.kaiAuthMode);if(wrap)wrap.classList.toggle("hidden",!needed);
 if(!needed){kaiHumanChallenge=null;return}
 const shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
 host.innerHTML="";if(answer){answer.value="";answer.classList.add("hidden")}if(math)math.classList.add("hidden");
 if(Math.random()<0.94){
  const task=KAI_HUMAN_TASKS[Math.floor(Math.random()*KAI_HUMAN_TASKS.length)],target=task[0],targets=task[1],decoys=task[2],tiles=[];
  const count=2+Math.floor(Math.random()*4);
  for(let i=0;i<count;i++)tiles.push({emoji:targets[Math.floor(Math.random()*targets.length)],correct:true});
  while(tiles.length<12)tiles.push({emoji:decoys[Math.floor(Math.random()*decoys.length)],correct:false});
  shuffle(tiles);kaiHumanChallenge={type:"visual",selected:new Set(),expected:new Set(tiles.map((t,i)=>t.correct?i:null).filter(i=>i!==null))};
  q.textContent="Select all the "+target+".";
  tiles.forEach((t,i)=>{const b=document.createElement("button");b.type="button";b.dataset.selected="false";b.setAttribute("aria-pressed","false");b.setAttribute("aria-label","Tile "+(i+1));b.textContent=t.emoji;b.style.cssText="min-height:48px;border:1px solid var(--line);border-radius:10px;background:#0b1228;color:var(--text);font-size:26px;cursor:pointer;transition:border-color .12s,background .12s";b.addEventListener("click",()=>{const selected=b.dataset.selected==="true";b.dataset.selected=String(!selected);b.setAttribute("aria-pressed",String(!selected));if(!selected){kaiHumanChallenge.selected.add(i);b.style.borderColor="var(--cyan)";b.style.background="#1c3150"}else{kaiHumanChallenge.selected.delete(i);b.style.borderColor="var(--line)";b.style.background="#0b1228"}});host.appendChild(b)});
 }else{
  const a=4+Math.floor(Math.random()*18),b=2+Math.floor(Math.random()*12),op=Math.random()<0.5?"+":"−",result=op==="+"?a+b:a-b;kaiHumanChallenge={type:"math",answer:String(result)};q.textContent="Solve this quick check:";if(math){math.classList.remove("hidden");math.textContent=a+" "+op+" "+b+" = ?"}if(answer)answer.classList.remove("hidden");
 }
}
function validateKaiHumanCheck(){
 if(!kaiHumanNeeded(window.kaiAuthMode))return;
 if(!kaiHumanChallenge)throw Error("Kai Human Check is loading. Please try again.");
 if(kaiHumanChallenge.type==="visual"){const selected=kaiHumanChallenge.selected,expected=kaiHumanChallenge.expected;if(selected.size!==expected.size||[...expected].some(i=>!selected.has(i)))throw Error("That selection isn't quite right. Try the new Kai Human Check.");}
 else if(String($("kaiHumanAnswer")?.value||"").trim()!==kaiHumanChallenge.answer)throw Error("That answer isn't correct. Try the new Kai Human Check.");
 try{sessionStorage.setItem("kaiHumanPassed","yes")}catch{}
}
