async function secureSessionGate(){if(!session||window.kaiMfaCheckInProgress||window.kaiMfaPending)return;window.kaiMfaCheckInProgress=true;try{await enforceMfaAfterPasswordSignIn();if(session)showApp()}catch(err){try{await sb.auth.signOut({scope:"local"})}catch{}session=null;authUI("signin",err.message||"Additional account verification is required. Sign in again.");$("appShell").classList.add("hidden");$("authShell").classList.remove("hidden")}finally{window.kaiMfaCheckInProgress=false}}
async function enforceMfaAfterPasswordSignIn(){const listed=await sb.auth.mfa.listFactors();if(listed.error)throw listed.error;const verified=(listed.data.totp||[]).filter(f=>f.status==="verified");if(!verified.length)return;const aal=await sb.auth.mfa.getAuthenticatorAssuranceLevel();if(aal.error)throw aal.error;if(aal.data.currentLevel==="aal2")return;const factor=verified[0];const challenge=await sb.auth.mfa.challenge({factorId:factor.id});if(challenge.error)throw challenge.error;const code=prompt("Two-factor authentication is enabled. Enter the current code from your authenticator app.");if(!code||!/^\\d{6}$/.test(code.trim())){await sb.auth.signOut({scope:"local"});throw Error("Two-factor code required. Sign in again and enter your 6-digit code.");}const verifiedCode=await sb.auth.mfa.verify({factorId:factor.id,challengeId:challenge.data.id,code:code.trim()});if(verifiedCode.error){await sb.auth.signOut({scope:"local"});throw Error("The two-factor code was not accepted. Sign in again and try a current code.");}session=(await sb.auth.getSession()).data.session;}
async function startMfaEnrollment(){const b=$("mfaStart");b.disabled=true;try{const {data,error}=await sb.auth.mfa.enroll({factorType:"totp",friendlyName:"Kai.AI authenticator"});if(error)throw error;const factor=data;const area=$("mfaEnrollArea");area.innerHTML='<div class="item"><strong>1. Scan this QR code</strong><p class="muted small">Scan with your authenticator app. If scanning does not work, use the setup key shown below.</p><img alt="Authenticator setup QR code" style="display:block;max-width:220px;background:white;padding:10px;border-radius:10px;margin:12px auto" src="'+factor.totp.qr_code+'"><label>SETUP KEY</label><code style="display:block;overflow-wrap:anywhere">'+esc(factor.totp.secret)+'</code><p class="muted small">2. Enter the six-digit code from your app to finish setup.</p></div>';const verifyArea=$("mfaVerifyArea");verifyArea.innerHTML='<form id="mfaVerifyForm"><div class="field"><label>AUTHENTICATOR CODE</label><input id="mfaCode" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" minlength="6" required autocomplete="one-time-code"></div><button class="btn primary" type="submit">Verify and enable 2FA</button><button class="btn" id="mfaCancel" type="button" style="margin-left:6px">Cancel setup</button></form>';const ch=await sb.auth.mfa.challenge({factorId:factor.id});if(ch.error)throw ch.error;$("mfaVerifyForm").onsubmit=async e=>{e.preventDefault();const submit=e.submitter;if(submit)submit.disabled=true;try{const result=await sb.auth.mfa.verify({factorId:factor.id,challengeId:ch.data.id,code:$("mfaCode").value.trim()});if(result.error)throw result.error;toast("Two-factor authentication is enabled.","good");session=(await sb.auth.getSession()).data.session;await render()}catch(err){toast(err.message||"Could not verify authenticator code.","bad");if(submit)submit.disabled=false}};$("mfaCancel").onclick=async()=>{try{await sb.auth.mfa.unenroll({factorId:factor.id})}catch{}await render()};}catch(err){toast(err.message||"Could not start 2FA setup.","bad")}finally{if($("mfaStart"))$("mfaStart").disabled=false}}
async function removeMfaFactor(id){if(!confirm("Remove this authenticator? Your account will have less protection if this is your only factor."))return;try{const {error}=await sb.auth.mfa.unenroll({factorId:id});if(error)throw error;await sb.auth.refreshSession();toast("Authenticator removed.","good");await render()}catch(err){toast(err.message||"Could not remove authenticator.","bad")}}
async function signOutOtherSessions(){if(!confirm("Sign out other active Kai.AI sessions? This browser stays signed in."))return;try{const {error}=await sb.auth.signOut({scope:"others"});if(error)throw error;toast("Sign-out request for other sessions completed.","good")}catch(err){toast(err.message||"Could not sign out other sessions.","bad")}}
async function signOutEverywhere(){if(!confirm("Sign out of every Kai.AI session, including this browser?"))return;try{const {error}=await sb.auth.signOut({scope:"global"});if(error)throw error;session=null;authUI("signin","You have signed out everywhere.");$("appShell").classList.add("hidden");$("authShell").classList.remove("hidden")}catch(err){toast(err.message||"Could not sign out everywhere.","bad")}}
async function changeAccountPassword(e){e.preventDefault();const current=$("currentAccountPassword").value,value=$("newAccountPassword").value;if(!current){toast("Enter your current password to confirm this change.","bad");return}if(value.length<12){toast("Use a password with at least 12 characters.","bad");return}if(current===value){toast("Choose a new password different from your current password.","bad");return}const b=e.submitter;if(b)b.disabled=true;try{const {error}=await sb.auth.updateUser({current_password:current,password:value});if(error)throw error;$("changePasswordForm").reset();toast("Password updated. If you did not request this, sign out other sessions immediately.","good")}catch(err){toast(err.message||"Could not update password.","bad")}finally{if(b)b.disabled=false}}
