 document.body.appendChild(modal);$("kaiGameClose").onclick=kaiCloseMiniGame;modal.addEventListener("click",e=>{if(e.target===modal)kaiCloseMiniGame()});
 const stage=$("kaiGameStage"),status=$("kaiGameStatus");let timer=null,score=0,turn=0,secret=Math.floor(Math.random()*20)+1,tries=5,sequence=[],pos=0,board=Array(9).fill(""),over=false;
